from pathlib import Path
import argparse,json
import pandas as pd,numpy as np
from nba_api.stats.static import teams

def paired(file):
 f=pd.read_csv(file);on=f[f.condition.eq('on')];off=f[f.condition.eq('off')];return on.merge(off,on=['TEAM_ID','VS_PLAYER_ID'],suffixes=('_on','_off'),validate='one_to_one')
def main(argv=None):
 p=argparse.ArgumentParser();p.add_argument('--output-dir',type=Path,default=Path(__file__).resolve().parent/'nba_passing_output');p.add_argument('--data-dir',type=Path);a=p.parse_args(argv);root=a.output_dir;out=a.data_dir or root/'onoff_dependency';source=root/'2025-26/team_season_topics';P=pd.read_csv(source/'player_games.csv',dtype={'GAME_ID':str});G=pd.read_csv(source/'team_games.csv',dtype={'GAME_ID':str});G['date']=pd.to_datetime(G.GAME_DATE);candidates=[];chosen=[]
 for team in teams.get_teams():
  name=team['abbreviation'];tid=team['id'];g=G[G.TEAM_ID.eq(tid)].sort_values(['date','GAME_ID']);early=set(g.head(10).GAME_ID);retained=set(P[P.TEAM_ID.eq(tid)&P.GAME_ID.isin(early)].PLAYER_ID);q=paired(out/'onoff/2024-25'/(name+'.csv'));q['gap']=q.OFF_RATING_on-q.OFF_RATING_off;q['eligible_minutes']=q.MIN_on.ge(1000)&q.MIN_off.ge(500);q['retained_first10']=q.VS_PLAYER_ID.isin(retained);q['team']=name;candidates.append(q);eligible=q[q.eligible_minutes&q.retained_first10].sort_values(['gap','VS_PLAYER_ID'],ascending=[False,True]);assert len(eligible)>0,name
  z=eligible.iloc[0];pid=int(z.VS_PLAYER_ID);other=P[P.PLAYER_ID.eq(pid)&P.TEAM_ID.ne(tid)];otherdate=pd.to_datetime(other.GAME_DATE).min() if len(other) else pd.NaT;censor=otherdate-pd.Timedelta(days=14) if pd.notna(otherdate) else pd.NaT;window=g[g.date.lt(censor)] if pd.notna(censor) else g;present=set(P[P.TEAM_ID.eq(tid)&P.PLAYER_ID.eq(pid)].GAME_ID);ngp=window.GAME_ID.isin(present).sum();curr=paired(out/'onoff/2025-26'/(name+'.csv'));cur=curr[curr.VS_PLAYER_ID.eq(pid)];assert len(cur)==1,name;cur=cur.iloc[0]
  actualname=P[P.PLAYER_ID.eq(pid)].PLAYER_NAME.iloc[0];chosen.append(dict(team=name,team_id=tid,star_id=pid,star_name=actualname,prior_on_off_gap=float(z.gap),prior_on_ortg=z.OFF_RATING_on,prior_off_ortg=z.OFF_RATING_off,prior_on_minutes=z.MIN_on,prior_off_minutes=z.MIN_off,current_on_ortg=cur.OFF_RATING_on,current_off_ortg=cur.OFF_RATING_off,current_on_off_gap=cur.OFF_RATING_on-cur.OFF_RATING_off,current_on_minutes=cur.MIN_on,current_off_minutes=cur.MIN_off,present_games=int(ngp),absent_games=int(len(window)-ngp),window_games=len(window),window_start=window.date.min().date().isoformat(),window_end=window.date.max().date().isoformat(),trade_censor_date=str(censor.date()) if pd.notna(censor) else '',first_other_team_date=str(otherdate.date()) if pd.notna(otherdate) else '',star_selection='2024-25 largest on-off offensive-rating gap among eligible retained players'))
 pd.concat(candidates).to_csv(out/'all_prior_candidates.csv',index=False);d=pd.DataFrame(chosen).sort_values(['prior_on_off_gap','team'],ascending=[False,True]);d.insert(0,'dependency_rank',range(1,len(d)+1));d.to_csv(out/'selected_stars.csv',index=False);print(d[['team','star_name','prior_on_off_gap','current_on_off_gap','present_games','absent_games','window_games','trade_censor_date']].to_string(index=False))
if __name__=='__main__':main()
